if self.query.combinator:
    src = resolved.get_source_expressions()[0]
    # Relabel order by columns to raw numbers if this is a combined
    # query; necessary since the columns can't be referenced by the
    # fully qualified name and the simple column names may collide.
    for idx, (sel_expr, _, col_alias) in enumerate(self.select):
        if is_ref and col_alias == src.refs:
            src = src.source
        elif col_alias:
            continue
        if src == sel_expr:
            resolved.set_source_expressions([RawSQL('%d' % (idx + 1), ())])
            break
    else:
        # The ordering column was not in the select (e.g. the
        # select was narrowed via values()/values_list()).  Add
        # it so that the positional ORDER BY reference is valid
        # and so that get_combinator_sql propagates it to the
        # inner sub-queries.
        try:
            sql, params = self.compile(src, select_format=True)
        except EmptyResultSet:
            sql, params = '0', ()
        idx = len(self.select)
        self.select.append((src, (sql, params), None))
        # Propagate to inner combined queries via values_select.
        field_name = getattr(src, 'target', None)
        if field_name is not None and hasattr(field_name, 'attname'):
            attname = field_name.attname
            if attname not in self.query.values_select:
                self.query.values_select = tuple(self.query.values_select) + (attname,)
        resolved.set_source_expressions([RawSQL('%d' % (idx + 1), ())])
